/**
 * The running test's steps in plain English: "Open the home page (/)", "Click "Services" in the
 * header", "Check that the submit button is shown". Every action and check in the suite adds its step
 * here, and each is printed as it happens, so a run's output reads like the story it tests. When a
 * test fails, BaseTest prints the step it failed at, and why.
 */
public final class StepLog {
    private static final ThreadLocal<List<String>> STEPS = ThreadLocal.withInitial(ArrayList::new);

    private StepLog() {
    }

    /** Starts a new test's log. BaseTest calls this before every test. */
    public static void start() {
        STEPS.get().clear();
    }

    /** A step the test takes, as a visitor would say it: step("Type the email address"). */
    public static void step(String sentence) {
        List<String> steps = STEPS.get();
        steps.add(sentence);
        System.out.println(Theme.step("   " + steps.size() + ". " + sentence));
    }

    /** A remark that is not a step of its own, e.g. "now on the services page". */
    public static void note(String remark) {
        System.out.println(Theme.note("      " + remark));
    }

    /** The steps so far, in order. */
    public static List<String> steps() {
        return List.copyOf(STEPS.get());
    }

    /**
     * Why something failed, in one line. Playwright's errors start "Error {" with the reason on the
     * lines below, then a call log of what it tried; this keeps the reason and the last thing the
     * log says ("element is not visible", "<div id=...> intercepts pointer events").
     */
    public static String reason(Throwable cause) {
        String message = cause.getMessage();
        if (message == null || message.isBlank()) return cause.getClass().getSimpleName();
        int start = message.indexOf("message='");
        if (start >= 0) {
            message = message.substring(start + "message='".length());
            int end = message.indexOf("\n  name='");
            if (end >= 0) message = message.substring(0, end);
        }
        String[] lines = message.split("\n");
        String first = lines[0].trim();
        String seen = "";
        for (String line : lines) {
            String entry = line.trim();
            if (!entry.startsWith("- ")) continue;
            entry = entry.substring(2).trim();
            if (entry.startsWith("retrying") || entry.startsWith("attempting") || isShortWait(entry)) continue;
            if (seen.contains("intercepts pointer events") && !entry.contains("intercepts pointer events")) continue;
            seen = entry;
        }
        if (seen.length() > 240) seen = seen.substring(0, 240) + "...";
        return seen.isEmpty() || first.contains(seen) ? first : first + " (Playwright saw: " + seen + ")";
    }

    /** "waiting 20ms", "waiting 100ms": Playwright pausing between tries, not news. */
    private static boolean isShortWait(String entry) {
        if (!entry.startsWith("waiting ") || !entry.endsWith("ms")) return false;
        String number = entry.substring("waiting ".length(), entry.length() - 2);
        return !number.isEmpty() && number.chars().allMatch(Character::isDigit);
    }

    /** What BaseTest prints when a test fails: the step it failed at, and why. */
    public static String failure(Throwable cause) {
        List<String> steps = STEPS.get();
        String reason = reason(cause);
        if (steps.isEmpty()) return "   FAILED before its first step, because: " + reason;
        return "   FAILED at step " + steps.size() + ": " + steps.get(steps.size() - 1) + "\n   because: " + reason;
    }

    // ==== YOURS (extras): safe to edit; regenerating keeps what is between these lines ====
    // ==== END YOURS (extras) ====
}
